/*
  O'ahu Road Trip question bank.

  Every question is ORIGINAL wording written to test a fact from the official
  Hawaii Driver's Manual (Hawaii Department of Transportation, English edition,
  HPC 10/18 printing). "src" gives the manual page so players can look it up.
  The manual's own test questions are not reproduced here.

  Format: c[0] is always the correct answer. Choices are shuffled at runtime.
  Topics map to the stops on the O'ahu map (see game.js STOPS).
*/
window.ORT_QUESTIONS = [
  // ---------------- PERMIT BASICS (Kapolei) ----------------
  { id: "b1", t: "basics", q: "What is the youngest age you can get a Hawaii instruction permit?", c: ["15 and a half", "15", "16", "14 and a half"], why: "Hawaii's minimum age for an instruction permit is 15 1/2.", src: "p. 13" },
  { id: "b2", t: "basics", q: "With an instruction permit, your supervising driver must be:", c: ["Licensed for that vehicle and at least 21", "Any licensed driver 18 or older", "Any adult in the car", "A certified driving instructor only"], why: "A permit holder can only drive with a licensed driver who is at least 21.", src: "p. 11, 13" },
  { id: "b3", t: "basics", q: "When you drive a car on a permit, where must your supervising driver sit?", c: ["Right front passenger seat", "Directly behind you", "Any seat in the car", "Back seat, middle"], why: "In every vehicle except motorcycles, the licensed supervisor sits in the right front seat.", src: "p. 11" },
  { id: "b4", t: "basics", q: "You have a permit and want to drive at 11:30 p.m. Who must be with you?", c: ["Your parent or guardian", "Any licensed driver 21 or older", "Any licensed friend", "Nobody. Permit holders can't drive after 11 p.m. at all"], why: "Between 11 p.m. and 5 a.m., a permit holder must be accompanied by a parent or guardian.", src: "p. 13" },
  { id: "b5", t: "basics", q: "How long must you hold your instruction permit before applying for a provisional license?", c: ["180 days", "30 days", "90 days", "One full year"], why: "You need to hold a valid permit for 180 days first.", src: "p. 13" },
  { id: "b6", t: "basics", q: "What is the minimum age for a provisional license?", c: ["16", "15 and a half", "17", "18"], why: "You must be at least 16 to get a provisional license.", src: "p. 13" },
  { id: "b7", t: "basics", q: "Before getting a provisional license, what course must you complete?", c: ["A state-certified driver's ed course (classroom and behind-the-wheel)", "A first aid and CPR course", "A car maintenance course", "A motorcycle safety course"], why: "You need both the classroom and behind-the-wheel certificates from a state-certified driver's education course.", src: "p. 13" },
  { id: "b8", t: "basics", q: "With a provisional license, how many passengers under 18 who aren't household members can you drive?", c: ["One", "None", "Two", "Three"], why: "Provisional drivers may carry only one non-household passenger under 18 (unless a parent or guardian is with them).", src: "p. 13, 14" },
  { id: "b9", t: "basics", q: "If you're under 18, what do you need to apply for a permit?", c: ["Written consent from a parent or legal guardian", "A letter from your school", "Proof of a job", "Nothing extra"], why: "Applicants under 18 need written consent from a parent or legal guardian (unless married or emancipated).", src: "p. 13" },
  { id: "b10", t: "basics", q: "Which tests do you pass to get your instruction permit?", c: ["A vision screening and a rules-of-the-road written test", "A road test and parallel parking", "Only a vision test", "A road test only"], why: "The permit's preliminary exams are a vision screening and a rules-of-the-road test.", src: "p. 13" },
  { id: "b11", t: "basics", q: "What's the minimum age for a full (non-provisional) Hawaii driver's license?", c: ["17", "16", "18", "21"], why: "You can get a full driver's license at 17, after holding a provisional license for six months.", src: "p. 14" },
  { id: "b12", t: "basics", q: "How long must you hold a provisional license before applying for a full license?", c: ["Six months", "Three months", "One year", "Two years"], why: "Provisional drivers must hold that license for six months first.", src: "p. 14" },
  { id: "b13", t: "basics", q: "While driving, your license must be:", c: ["With you at all times, shown to police on request", "At home in a safe place", "In the glove box only on long trips", "Photographed on your phone"], why: "You must carry a valid license whenever you drive and show it to a police officer on demand.", src: "p. 17" },
  { id: "b14", t: "basics", q: "You move to a new address. How soon must you tell the county examiner of drivers?", c: ["Within 30 days", "Within 10 days", "Within 6 months", "At your next renewal"], why: "Report an address change in writing within 30 days.", src: "p. 16" },
  { id: "b15", t: "basics", q: "When you drive on a permit, who has to wear a seat belt or be in a child restraint?", c: ["Everyone in the car", "Only you", "Only front-seat riders", "Only passengers under 18"], why: "All occupants must use safety belts or child restraints.", src: "p. 13" },

  // ---------------- LANES & LINES (Pearl City) ----------------
  { id: "l1", t: "lines", q: "Yellow center lines separate traffic that is:", c: ["Moving in opposite directions", "Moving in the same direction", "Parked along the curb", "Turning right"], why: "Yellow lines divide opposite directions. White lines divide lanes going the same way.", src: "p. 33" },
  { id: "l2", t: "lines", q: "White lane lines separate traffic that is:", c: ["Moving in the same direction", "Moving in opposite directions", "Only buses and taxis", "Bicycles from cars"], why: "White lines separate lanes moving the same direction.", src: "p. 34" },
  { id: "l3", t: "lines", q: "On a two-lane road with a single BROKEN yellow center line, you may:", c: ["Cross it to pass when it's safe", "Never cross it", "Cross it only to park", "Drive on it to avoid potholes"], why: "A broken yellow center line lets you cross to pass, but only when it's safe.", src: "p. 33" },
  { id: "l4", t: "lines", q: "When can you cross DOUBLE SOLID yellow lines?", c: ["Only to turn left into or out of an alley, private road or driveway", "To pass a slow car", "Any time no one is coming", "Never, for any reason"], why: "Double solid yellow means no passing in either direction. You can only cross to make that left turn.", src: "p. 33" },
  { id: "l5", t: "lines", q: "Double solid WHITE lines between lanes mean:", c: ["You must not cross them", "Cross only with great care", "Cross freely when safe", "Bus lane only"], why: "Moving lane to lane across double solid white lines is prohibited.", src: "p. 35" },
  { id: "l6", t: "lines", q: "A single SOLID white line between lanes means:", c: ["Changing lanes is hazardous. Cross only in unusual cases, with great care", "Change lanes any time", "It's a bike lane", "You must change lanes here"], why: "Solid white warns that lane changes are hazardous. The wider the line, the greater the hazard.", src: "p. 34" },
  { id: "l7", t: "lines", q: "At night you see RED reflectors on the lane markings in front of you. This means:", c: ["You're going the wrong way. Don't enter or use this roadway", "A bus stop is ahead", "Slow down for a curve", "A fire hydrant is nearby"], why: "Red pavement markings or reflectors mark a road you must not enter. Seeing them means you're facing the wrong way.", src: "p. 35, 77" },
  { id: "l8", t: "lines", q: "The center lane marked with solid AND dashed yellow lines (two-way left turn lane) can be used for:", c: ["Left turns only, from either direction", "Passing slow traffic", "Parking briefly", "Driving straight in heavy traffic"], why: "It's only for left turns, from either direction. Never use it for passing.", src: "p. 36" },
  { id: "l9", t: "lines", q: "YELLOW obstruction markings guide you around something in the road. You must pass:", c: ["Only to the right of them", "Only to the left of them", "On either side", "Straight over them"], why: "You can pass either side of white obstruction markings, but only to the right of yellow ones.", src: "p. 37" },
  { id: "l10", t: "lines", q: "A big white \"X\" with two \"R\"s painted in your lane warns you of:", c: ["A railroad crossing ahead", "A roundabout ahead", "A road closure", "A school zone"], why: "That's the railroad crossing pavement marking.", src: "p. 38" },
  { id: "l11", t: "lines", q: "A solid white line painted across your lane at an intersection shows:", c: ["The exact spot to stop", "Where to speed up", "The start of a passing zone", "A bike lane"], why: "Stop lines show exactly where to stop.", src: "p. 36" },
  { id: "l12", t: "lines", q: "Traffic islands (painted, curbed or landscaped) should be:", c: ["Never driven into or across", "Used as a turn lane", "Crossed when traffic is light", "Used for parking"], why: "Never drive into or across a traffic island.", src: "p. 38" },
  { id: "l13", t: "lines", q: "Arrows painted in your lane point both straight and right. You may:", c: ["Go either direction shown", "Only go straight", "Only turn right", "Turn left too"], why: "If the arrows show more than one direction, you can pick any of them.", src: "p. 37" },
  { id: "l14", t: "lines", q: "The edge line along the RIGHT side of the road is:", c: ["White", "Yellow", "Red", "Blue"], why: "White edge lines mark the right edge. Yellow edge lines can appear on the left of divided roads.", src: "p. 35" },

  // ---------------- SIGNALS (Downtown Honolulu) ----------------
  { id: "s1", t: "signals", q: "At a red light with no stop line or crosswalk, where do you stop?", c: ["Before entering the intersection", "In the middle of the intersection", "Wherever the car ahead stops", "After the intersection"], why: "Stop at the stop line. If there isn't one, stop before the crosswalk. If there's no crosswalk either, stop before the intersection.", src: "p. 39" },
  { id: "s2", t: "signals", q: "Can you turn right on a red light in Hawaii?", c: ["Yes, after a full stop, unless a sign says no, yielding to everyone", "Yes, without stopping if it's clear", "Never", "Only between midnight and 5 a.m."], why: "After stopping, a right on red is allowed unless a sign prohibits it. You must yield to pedestrians and vehicles.", src: "p. 39" },
  { id: "s3", t: "signals", q: "When can you turn LEFT on a red light?", c: ["From a one-way street onto a one-way street going left, after stopping", "Never in Hawaii", "Any time after stopping", "Only if a police officer is there"], why: "After a full stop, you can turn left on red from a one-way street onto a one-way street moving left, unless a sign prohibits it.", src: "p. 39" },
  { id: "s4", t: "signals", q: "A steady YELLOW light means:", c: ["Red is coming next. Avoid entering the intersection", "Speed up to beat the red", "Stop immediately, even mid-intersection", "Go, the way is clear"], why: "Yellow warns that red comes next, so avoid entering. Never enter after the light turns red.", src: "p. 39" },
  { id: "s5", t: "signals", q: "Your light turns green but a pedestrian is still crossing. You must:", c: ["Yield to the pedestrian and any cars still in the intersection", "Honk and go", "Go around the pedestrian", "Go, you have the green"], why: "Green means go, but you must still yield to pedestrians and vehicles already in the intersection.", src: "p. 32, 40" },
  { id: "s6", t: "signals", q: "A lit GREEN ARROW means:", c: ["You may go, but only in the arrow's direction", "Go any direction you want", "Yield to oncoming traffic, then go any way", "Stop and wait"], why: "A green arrow works like a green light, but you must move in the direction it points.", src: "p. 40" },
  { id: "s7", t: "signals", q: "A FLASHING RED traffic light means the same as:", c: ["A stop sign", "A yield sign", "A yellow light", "A green light"], why: "Flashing red equals a stop sign.", src: "p. 41" },
  { id: "s8", t: "signals", q: "A FLASHING YELLOW light means:", c: ["Proceed with caution", "Stop and wait for green", "The light is broken. Treat it as green", "Pedestrians only"], why: "Flashing yellow means you may go, but carefully.", src: "p. 41" },
  { id: "s9", t: "signals", q: "Above your lane you see a RED \"X\" signal. You should:", c: ["Not drive in that lane", "Use the lane carefully", "Use the lane to turn left only", "Speed up to clear the lane"], why: "A red X means the lane is being used by traffic coming the other way. Don't use it.", src: "p. 41" },
  { id: "s10", t: "signals", q: "A STEADY yellow \"X\" lane signal means:", c: ["Move out of that lane, it's about to switch direction", "The lane is open, go ahead", "Bus lane only", "Speed limit drops"], why: "A steady yellow X warns the lane will soon carry opposite traffic. Move out.", src: "p. 42" },
  { id: "s11", t: "signals", q: "A FLASHING yellow \"X\" lane signal means you may use that lane:", c: ["Only to get ready for a left turn", "For passing", "For any purpose", "Only if you're a bus"], why: "A flashing yellow X means the lane is only for preparing a left turn.", src: "p. 42" },
  { id: "s12", t: "signals", q: "The pedestrian signal shows a FLASHING upraised hand (DON'T WALK). Pedestrians:", c: ["Shouldn't start crossing, but those already crossing can finish", "Can start crossing quickly", "Must stop in the middle of the road", "Can cross diagonally"], why: "A flashing DON'T WALK means don't start. Anyone already in the street continues to the curb or island.", src: "p. 42" },
  { id: "s13", t: "signals", q: "A RED ARROW for your turn lane means:", c: ["Same as a red light for that lane", "Turn carefully", "Yield, then turn", "The arrow is off. Go"], why: "A red arrow has the same meaning as a red light for that lane.", src: "p. 40" },

  // ---------------- RIGHT OF WAY (Waikiki) ----------------
  { id: "r1", t: "row", q: "You and another car reach an intersection with no signs or signals at the same time. Who goes first?", c: ["The car on the right", "The car on the left", "The faster car", "Whoever honks first"], why: "When you arrive at the same time, yield to the vehicle on your right.", src: "p. 32" },
  { id: "r2", t: "row", q: "When turning LEFT at an intersection, you must yield to:", c: ["Oncoming traffic close enough to be a hazard", "Nobody, left turns have priority", "Only trucks and buses", "Cars behind you"], why: "Left-turning drivers yield to oncoming traffic that's close enough to be a hazard.", src: "p. 32" },
  { id: "r3", t: "row", q: "You're pulling out of a driveway onto the street. You must:", c: ["Stop before the sidewalk and yield to all traffic and pedestrians", "Honk and pull out", "Pull out fast to merge", "Stop only if a car is coming"], why: "Always stop before crossing the sidewalk, then yield. Failing to stop is illegal.", src: "p. 32, 64" },
  { id: "r4", t: "row", q: "You hear a siren and see flashing lights coming up behind you. You should:", c: ["Slow down, pull out of its path and stop", "Speed up to stay ahead", "Slam on your brakes right where you are", "Keep going at the same speed"], why: "Give emergency vehicles a clear path and stop. Don't panic-brake.", src: "p. 29" },
  { id: "r5", t: "row", q: "You're stuck in heavy traffic and an ambulance is right behind you. You should:", c: ["Keep moving slowly until you can safely get out of the way", "Stop right away in your lane", "Back up to make room", "Drive onto the sidewalk"], why: "In heavy traffic, keep moving slowly until you can safely clear a path.", src: "p. 29" },
  { id: "r6", t: "row", q: "A police car is stopped on the shoulder with lights flashing. If it's safe, you should:", c: ["Slow down and move over to leave an empty lane between you", "Keep your speed and lane", "Stop next to it", "Honk to let them know you're passing"], why: "Slow down and, if safe, move over so a lane separates you from the stopped emergency vehicle.", src: "p. 29" },
  { id: "r7", t: "row", q: "A funeral procession is going through an intersection. You should:", c: ["Let it pass. Don't drive between its cars", "Cut in if there's a gap", "Honk to speed it up", "Follow it closely"], why: "Funeral processions have the right of way at intersections. Don't drive between the vehicles.", src: "p. 29" },
  { id: "r8", t: "row", q: "A person with a white cane or guide dog is crossing in front of you. You must:", c: ["Stop, no matter what the light says", "Go if you have a green light", "Honk to warn them", "Drive slowly around them"], why: "Always stop for a blind pedestrian in the roadway, whatever the signal shows.", src: "p. 95" },
  { id: "r9", t: "row", q: "The car in the next lane has stopped to let a pedestrian cross. You:", c: ["Must not pass it", "Can pass carefully", "Should honk and pass", "Can pass if you're turning"], why: "It's illegal to pass a vehicle stopped for a pedestrian.", src: "p. 95" },
  { id: "r10", t: "row", q: "A school bus is stopped ahead in your lane with red lights flashing. You must:", c: ["Stop before reaching it and wait until it moves or the lights turn off", "Pass slowly on the left", "Slow to 15 mph and pass", "Honk and pass"], why: "Stop for a school bus with flashing red lights until it moves again or the lights go off.", src: "p. 96" },
  { id: "r11", t: "row", q: "You're on a DIVIDED highway going the opposite direction from a stopped school bus with red lights flashing. You:", c: ["Aren't required to stop, but stay alert for children", "Must stop", "Must change lanes", "Must honk"], why: "On a divided highway, traffic going the opposite way doesn't have to stop.", src: "p. 96" },
  { id: "r12", t: "row", q: "Failing to stop for a school bus with flashing red lights can cost you up to:", c: ["$1,000", "$50", "$100", "Nothing, it's a warning"], why: "The manual warns the fine can be $1,000.", src: "p. 96" },
  { id: "r13", t: "row", q: "Entering a roundabout, you must yield to:", c: ["Traffic already circling in it, plus pedestrians and bikes", "Nobody, entering cars have priority", "Only trucks", "Cars behind you"], why: "Entering traffic yields to traffic already in the roundabout, and to pedestrians and bicyclists.", src: "p. 65" },
  { id: "r14", t: "row", q: "Which way do you drive around a roundabout?", c: ["Counterclockwise, to the right of the center island", "Clockwise", "Whichever way is shorter", "Straight across the center"], why: "Keep to the right of the central island and go counterclockwise.", src: "p. 65" },
  { id: "r15", t: "row", q: "You miss your exit in a roundabout. You should:", c: ["Go around again to your exit", "Stop and back up", "Cut across the center island", "Exit anywhere and make a U-turn"], why: "Just drive around again until you reach your exit.", src: "p. 65" },
  { id: "r16", t: "row", q: "Pedestrians are in a marked crosswalk ahead. You must:", c: ["Stop for them", "Slow down and weave around them", "Honk so they hurry", "Only stop if there's a signal"], why: "You must stop for pedestrians in crosswalks.", src: "p. 36" },

  // ---------------- SIGNS (Hawaii Kai) ----------------
  { id: "g1", t: "signs", q: "An 8-sided red sign with white letters means:", c: ["Stop completely", "Yield", "Slow down", "Do not enter"], why: "The octagon is a stop sign. Make a full stop and yield before going.", src: "p. 44", sign: "stop" },
  { id: "g2", t: "signs", q: "A red-and-white downward triangle means:", c: ["Yield. Be ready to stop if traffic has the right of way", "Stop every time", "Warning: hill ahead", "Railroad crossing"], why: "Yield means slow down and stop only if there's traffic with the right of way.", src: "p. 44", sign: "yield" },
  { id: "g3", t: "signs", q: "A yellow diamond-shaped sign usually means:", c: ["Warning of a possible hazard ahead", "A required action", "A road work zone", "Directions to a city"], why: "Yellow, almost always diamond-shaped, warns of hazards.", src: "p. 43, 47", sign: "warning" },
  { id: "g4", t: "signs", q: "ORANGE signs warn you about:", c: ["Road work and construction", "School zones", "Hospitals", "Scenic spots"], why: "Orange is the color of road work and construction zones.", src: "p. 43, 49", sign: "construction" },
  { id: "g5", t: "signs", q: "Black-and-white rectangular signs (like speed limits) tell you:", c: ["A required action or rule", "Directions and services", "A warning only", "A suggestion"], why: "Black and white means a required action. These signs are always rectangular.", src: "p. 43", sign: "speed" },
  { id: "g6", t: "signs", q: "Green, blue and brown signs are:", c: ["Guide and information signs", "Warning signs", "Construction signs", "Stop signs"], why: "Green, blue and brown are used on guide and information signs.", src: "p. 43", sign: "guide" },
  { id: "g7", t: "signs", q: "On a traffic sign, the color RED means:", c: ["An action is prohibited", "Go", "Information", "Road work"], why: "Red means something is prohibited.", src: "p. 43" },
  { id: "g8", t: "signs", q: "A yellow-and-black PENNANT-shaped sign on the left side of the road marks:", c: ["The start of a no-passing zone", "A school crossing", "A railroad crossing", "The end of the freeway"], why: "The pennant points to where the no-passing zone begins.", src: "p. 45", sign: "pennant" },
  { id: "g9", t: "signs", q: "A \"PASS WITH CARE\" sign means:", c: ["The no-passing zone has ended", "Passing is never allowed", "You must pass now", "A passing lane is for trucks only"], why: "It marks the end of a no-passing zone. Passing is allowed again, carefully.", src: "p. 46" },
  { id: "g10", t: "signs", q: "A \"REDUCED SPEED AHEAD\" sign means the new lower limit starts:", c: ["At the next speed limit sign", "Right at this sign", "One mile later", "Only at night"], why: "Start slowing now. The new limit begins at the next speed limit sign.", src: "p. 45" },
  { id: "g11", t: "signs", q: "At a stop sign with no stop line, you can't see cross traffic from where you stopped. You should:", c: ["Creep forward and stop again where you can see", "Go, you already stopped once", "Honk and go", "Back up"], why: "Stop before the crosswalk. If you still can't see, move ahead slowly and stop again.", src: "p. 44" },
  { id: "g12", t: "signs", q: "A sign with a red circle and a red diagonal slash means:", c: ["That vehicle or movement is prohibited", "That activity is encouraged", "A warning", "A detour"], why: "Exclusion signs with a red circle (and slash) prohibit a vehicle or movement.", src: "p. 46", sign: "noturn" },
  { id: "g13", t: "signs", q: "The triangular reflective \"slow-moving vehicle\" emblem is on vehicles built to travel:", c: ["25 mph or less", "35 mph or less", "45 mph or less", "Only at night"], why: "It's required on vehicles designed for 25 mph or less. Slow down and approach carefully.", src: "p. 30", sign: "smv" },
  { id: "g14", t: "signs", q: "In a work zone, barricade stripes slope DOWN to the RIGHT. You should:", c: ["Bear to the right", "Bear to the left", "Stop", "Speed up"], why: "Stripes sloping down to the right mean bear right.", src: "p. 50" },
  { id: "g15", t: "signs", q: "Work-zone flaggers wear orange and direct traffic using:", c: ["Red flags or STOP/SLOW paddles", "Whistles only", "Green lights", "Hand waves only"], why: "Flaggers use red flags or stop/slow paddles. Follow their directions.", src: "p. 51" },
  { id: "g16", t: "signs", q: "What do you do at a stop sign?", c: ["Come to a complete stop and yield before going", "Slow down and roll through if clear", "Stop only if a car is coming", "Honk and go"], why: "Always come to a complete stop at the stop line, then yield to approaching traffic.", src: "p. 44, 57", sign: "stop" },

  // ---------------- SPEED & SPACE (Waimanalo) ----------------
  { id: "p1", t: "speed", q: "Hawaii's basic speed law says you must never drive:", c: ["Faster than is safe for conditions, even under the limit", "Under the speed limit", "More than 5 mph over the limit", "Slower than the car ahead"], why: "Drive at a reasonable and prudent speed for the road, traffic, weather and light.", src: "p. 28" },
  { id: "p2", t: "speed", q: "What's the MINIMUM following distance in normal conditions?", c: ["2 seconds", "1 second", "1 car length", "10 feet"], why: "Keep at least a 2-second interval. You should never have less.", src: "p. 67" },
  { id: "p3", t: "speed", q: "How do you check your following distance?", c: ["Count seconds after the car ahead passes a fixed marker", "Count the car lengths", "Watch your speedometer", "Look at the car's license plate size"], why: "When the car ahead passes a pole or tree, count \"one thousand one, one thousand two.\"", src: "p. 67" },
  { id: "p4", t: "speed", q: "When it first starts to rain, the road is:", c: ["Extra slippery, because oil hasn't washed away yet", "Safer, because the dust is gone", "No different", "Only slippery after an hour"], why: "The first drops mix with oil on the road. Slow down and double your following distance.", src: "p. 75" },
  { id: "p5", t: "speed", q: "In rain, your following distance should be at least:", c: ["Twice the normal distance", "The same as normal", "Half the normal distance", "One car length"], why: "Allow at least twice your normal following distance on wet roads.", src: "p. 75" },
  { id: "p6", t: "speed", q: "How far ahead must you signal before turning or changing lanes?", c: ["At least 100 feet", "At least 10 feet", "Only as you turn", "At least 1 mile"], why: "Signal for at least 100 feet, about five car lengths. Signal longer at higher speeds.", src: "p. 27, 74" },
  { id: "p7", t: "speed", q: "Do you need to signal if no other cars are around?", c: ["Yes, every time", "No", "Only at night", "Only on the freeway"], why: "Signal every time, even when no one seems to be around.", src: "p. 27" },
  { id: "p8", t: "speed", q: "What's listed as the major cause of most crashes?", c: ["Excessive speed for conditions", "Flat tires", "Bad weather", "Bright headlights"], why: "Going too fast for conditions is the top cause.", src: "p. 28, 66" },
  { id: "p9", t: "speed", q: "You can't keep up with traffic and cars are backing up behind you. You should:", c: ["Pull off and let them pass, or take another route", "Keep going, they can wait", "Drive in the left lane", "Turn on your hazard lights and continue"], why: "Don't hold back traffic. Move right, pull off, or pick another route.", src: "p. 28" },
  { id: "p10", t: "speed", q: "Reduced speed limits apply near schools and playgrounds:", c: ["When children are present", "Only on weekends", "Only at night", "Never in Hawaii"], why: "Reduced limits are required near schools, playgrounds and school crossings when children are present.", src: "p. 28" },
  { id: "p11", t: "speed", q: "Stopped behind another car in traffic, you should be able to see:", c: ["Where its rear tires touch the road", "Only its roof", "Its license plate only", "Nothing, get as close as possible"], why: "That spacing leaves room to go around if the car ahead can't move.", src: "p. 70" },
  { id: "p12", t: "speed", q: "Why shouldn't you rest your foot on the brake while driving?", c: ["It flashes false stop signals at drivers behind you", "It's more comfortable", "It saves gas", "It's required"], why: "Riding the brake gives a false stop-lamp signal and wears your brakes.", src: "p. 27, 70" },
  { id: "p13", t: "speed", q: "A friend in another car challenges you to race. The smart move is:", c: ["Decline. Racing on public roads is illegal", "Race only on an empty road", "Race only a short distance", "Race only at night"], why: "Racing or speed contests on public roads are never allowed, and turning down a challenge shows maturity.", src: "p. 25, 28" },

  // ---------------- PASSING & PARKING (Kailua) ----------------
  { id: "k1", t: "passing", q: "You shouldn't pass near a hill or curve unless you can see clearly ahead for about:", c: ["700 to 1,000 feet", "50 feet", "200 feet", "One car length"], why: "Don't pass approaching a hill or curve without 700 to 1,000 feet of clear distance.", src: "p. 30" },
  { id: "k2", t: "passing", q: "Another car is passing you. You should:", c: ["Not speed up", "Speed up so they can't pass", "Move left", "Brake hard"], why: "It's illegal to increase your speed while being passed.", src: "p. 30" },
  { id: "k3", t: "passing", q: "You must not pass within how many feet of an intersection or railroad crossing?", c: ["100 feet", "10 feet", "25 feet", "1,000 feet"], why: "No passing within 100 feet of an intersection, railroad crossing, narrow bridge or tunnel.", src: "p. 26, 31" },
  { id: "k4", t: "passing", q: "After passing, when is it safe to move back into your lane?", c: ["When you can see the passed car in your inside rearview mirror", "As soon as your front bumper clears theirs", "After counting to two", "When the other driver waves"], why: "Return when the overtaken car appears in your inside rearview mirror.", src: "p. 68" },
  { id: "k5", t: "passing", q: "The car ahead is turning left. Can you pass on the right?", c: ["Yes, carefully, but never by driving onto the shoulder", "Yes, using the shoulder", "No, never", "Only if you honk first"], why: "You may pass on the right of a left-turning car, but never drive off the pavement to do it.", src: "p. 26, 68" },
  { id: "k6", t: "passing", q: "While passing, an oncoming car suddenly appears. You should:", c: ["Brake and get back behind the car you were passing", "Floor it to finish the pass", "Drive onto the shoulder", "Flash your lights and keep going"], why: "Brakes slow you faster than power speeds you up. Drop back behind.", src: "p. 68" },
  { id: "k7", t: "passing", q: "There's a solid yellow line on your side of the center line. You:", c: ["Must not pass", "Can pass if it's clear", "Can pass motorcycles only", "Can pass if you honk"], why: "A solid yellow line in your lane marks a no-passing zone.", src: "p. 31, 33" },
  { id: "k8", t: "passing", q: "The end of a no-passing zone means:", c: ["You can see farther ahead, but you still check before passing", "It's automatically safe to pass", "You must pass now", "Speed limit goes up"], why: "The end of the zone means better visibility, not a guarantee it's safe.", src: "p. 31" },
  { id: "k9", t: "passing", q: "According to the Hawaii manual, when you park on a hill (uphill or downhill) you should:", c: ["Turn your front wheels to the right, toward the curb, and set the parking brake", "Leave the wheels straight", "Turn the wheels left, toward traffic", "Leave the car in neutral"], why: "Turning wheels right means the car rolls away from traffic if the brakes fail. Always set the brake.", src: "p. 71" },
  { id: "k10", t: "passing", q: "When parallel parked, your curbside wheels must be within how far of the curb?", c: ["12 inches", "24 inches", "36 inches", "6 feet"], why: "Curbside wheels must be within 12 inches of the curb (or completely inside a marked stall).", src: "p. 73" },
  { id: "k11", t: "passing", q: "Step 1 of parallel parking: pull up even with the front car, about how far from it?", c: ["About 18 inches", "About 5 feet", "Touching it", "About 10 feet"], why: "Signal, stop even with the front car about 18 inches away, rear bumpers even.", src: "p. 72" },
  { id: "k12", t: "passing", q: "What's the longest you can leave a car parked on a public street in one spot?", c: ["24 hours", "72 hours", "One week", "No limit"], why: "Parking on a public street for more than 24 hours straight is prohibited.", src: "p. 29" },
  { id: "k13", t: "passing", q: "Before walking away from your parked car, you must:", c: ["Stop the engine, take the key, set the parking brake", "Leave it running if it's quick", "Leave the key in case of towing", "Only lock the doors"], why: "Stop the engine, remove the key, set the parking brake, and turn the wheels to the curb on a grade.", src: "p. 29" },
  { id: "k14", t: "passing", q: "The striped area next to an accessible (disabled) parking space is:", c: ["A no-parking access aisle, kept clear for ramps and lifts", "Extra parking for small cars", "A motorcycle spot", "OK for quick stops"], why: "The access aisle must stay clear so wheelchair lifts and ramps can be used.", src: "p. 29" },
  { id: "k15", t: "passing", q: "When backing up, you should:", c: ["Turn and look back, not just use your mirrors", "Rely on your mirrors", "Back up quickly to get it over with", "Honk and go"], why: "Mirrors show too little. Turn around and look, and back slowly.", src: "p. 64" },
  { id: "k16", t: "passing", q: "On a road with FOUR or more lanes, can you cross to the left half to pass?", c: ["No, not unless signs direct you to", "Yes, when it's clear", "Yes, at night", "Only for trucks"], why: "Don't drive on the left half of a road with four or more lanes unless signs tell you to.", src: "p. 26" },

  // ---------------- FREEWAY & WEATHER (Kaneohe / H-3) ----------------
  { id: "f1", t: "freeway", q: "Merging onto the freeway, you should:", c: ["Signal, match traffic speed when safe, and yield to vehicles already on the freeway", "Force traffic to brake for you", "Always stop at the end of the ramp", "Merge without checking your blind spot"], why: "When the entrance lane is clear, signal and build speed for a safe gap. Yield to freeway traffic; never force a merge. Congestion may require slowing or stopping earlier on the entrance lane. Follow signs, signals and current conditions.", src: "p. 78" , url: "https://hidot.hawaii.gov/highways/files/2024/11/2023-Hawaii-Drivers-Manual_5.375x8.375_Final-r3-Digital-071924web.pdf#page=78" },
  { id: "f2", t: "freeway", q: "The entrance ramp is jammed. What should you NOT do?", c: ["Creep to the very end of the ramp and stop", "Slow down or stop near the start of the ramp", "Wait for a clear gap", "Use your turn signal"], why: "In congestion, the manual advises slowing or stopping near the entrance rather than using up the whole entrance lane. Never force a merge or ignore a ramp signal. Stop if signs, traffic or safety require it.", src: "p. 78" , url: "https://hidot.hawaii.gov/highways/files/2024/11/2023-Hawaii-Drivers-Manual_5.375x8.375_Final-r3-Digital-071924web.pdf#page=78" },
  { id: "f3", t: "freeway", q: "You just missed your freeway exit. You should:", c: ["Keep going to the next exit", "Stop and back up", "Cross the gore point", "Make a U-turn through the median"], why: "Never stop or back up on the freeway. Take the next exit.", src: "p. 79, 80" },
  { id: "f4", t: "freeway", q: "On the freeway, through traffic should use:", c: ["The left or center lanes", "The right lane only", "The shoulder", "Any lane, it doesn't matter"], why: "Through traffic uses the left or center lanes. Keep the right lane open for entering and exiting cars.", src: "p. 79" },
  { id: "f5", t: "freeway", q: "On a road with three or more lanes your direction, the best lane for steady driving is usually:", c: ["A center lane", "The far right lane", "The far left lane", "The shoulder"], why: "Center lanes have fewer conflicts. Leave outer lanes for cars entering and leaving.", src: "p. 65" },
  { id: "f6", t: "freeway", q: "When exiting the freeway, slow down:", c: ["After you're completely on the exit ramp", "Before you leave the freeway lane", "While still in the left lane", "Only at the stop light"], why: "Keep your speed until you're fully on the exit ramp, then slow smoothly.", src: "p. 80" },
  { id: "f7", t: "freeway", q: "You need to go the opposite direction on the freeway. You should:", c: ["Take the next exit and re-enter going the other way", "Turn around through the median", "Back up to the last on-ramp", "Make a U-turn on the shoulder"], why: "Never cross the divider, turn around, or back up on a freeway.", src: "p. 79" },
  { id: "f8", t: "freeway", q: "Partial hydroplaning can start at about what speed on wet roads?", c: ["35 mph", "15 mph", "55 mph", "75 mph"], why: "Partial hydroplaning may start around 35 mph. At 55 mph in heavy rain, tires can lose contact completely.", src: "p. 75" },
  { id: "f9", t: "freeway", q: "Which helps prevent hydroplaning?", c: ["Good tread, correct tire pressure and slower speed", "Driving faster through water", "Lower tire pressure", "Using cruise control"], why: "Worn or under-inflated tires hydroplane at lower speeds. Slow down.", src: "p. 76" },
  { id: "f10", t: "freeway", q: "Driving in fog (like up on the Pali or Saddle Road), use:", c: ["Low-beam headlights", "High-beam headlights", "No lights", "Hazard lights while moving"], why: "High beams reflect off fog and make it harder to see. Use low beams and slow way down.", src: "p. 76" },
  { id: "f11", t: "freeway", q: "In fog you can't see two car lengths (about 40 feet). You should:", c: ["Pull completely off the road, stop, and turn on hazard lights", "Keep going with high beams", "Follow the taillights ahead closely", "Speed up to get through it"], why: "If visibility is under 40 feet, get completely off the pavement and turn on your hazards.", src: "p. 76" },
  { id: "f12", t: "freeway", q: "Floodwater covers the road ahead and you cannot judge its depth. You should:", c: ["Turn around safely and find another route", "Follow a larger vehicle through", "Drive through if the water looks shallow", "Drive faster to avoid stalling"], why: "Do not drive onto a flooded road or around a flood barrier. Water can hide a washed-out road and can sweep away a vehicle. Do not use a guessed water depth as permission to enter.", src: "National Weather Service: flood safety" , url: "https://www.weather.gov/safety/flood-during" },
  { id: "f13", t: "freeway", q: "At night, an oncoming car's lights are blinding you. You should:", c: ["Look toward the right edge of the road", "Stare at the headlights", "Turn on your high beams", "Close one eye"], why: "Flash your high beams once if needed, then look to the right edge and follow lane markings.", src: "p. 77" },
  { id: "f14", t: "freeway", q: "When should you NOT use high beams?", c: ["When approaching or following other cars", "On empty rural roads at night", "When you can't see far ahead and no one's around", "Never use them"], why: "High beams blind other drivers. Dim them when approaching or following cars.", src: "p. 77" },
  { id: "f15", t: "freeway", q: "At dawn or dusk, you should:", c: ["Turn on low-beam headlights", "Keep lights off until full dark", "Use only parking lights", "Use high beams"], why: "Low light makes cars hard to see. Turn on low beams so others see you.", src: "p. 77" },
  { id: "f16", t: "freeway", q: "Rain is so heavy you can't see clearly even with wipers on. You should:", c: ["Pull onto the shoulder or a clear area and wait", "Speed up to get home faster", "Turn on high beams", "Follow the car ahead closely"], why: "If you can't see, pull off to a safe spot and stop until the rain lets up.", src: "p. 76" },

  // ---------------- SHARE THE ROAD (North Shore / Laie) ----------------
  { id: "h1", t: "share", q: "When passing a bicyclist, leave at least:", c: ["3 feet", "1 foot", "6 inches", "It doesn't matter"], why: "Keep at least 3 feet between your car and the bicyclist until you've safely passed.", src: "p. 97" },
  { id: "h2", t: "share", q: "Making a right turn where there's a bike lane, you should:", c: ["Check for bikes, yield, and cross the bike lane only as needed for a legal turn", "Use the bike lane as a shortcut through traffic", "Pass a cyclist and turn across their path", "Honk so cyclists must stop"], why: "Do not use a bike lane as a normal driving lane. Hawaii law permits entry while executing a legal turn, lane change or parking maneuver. Look for bicyclists, yield, and do not cut across their path.", src: "HRS 291C-123(a)(1); manual p. 67, 97" , url: "https://data.capitol.hawaii.gov/hrscurrent/Vol05_Ch0261-0319/HRS0291C/HRS_0291C-0123.htm" },
  { id: "h3", t: "share", q: "A motorcycle is entitled to:", c: ["The full width of its lane", "Half a lane", "The shoulder only", "Share a lane with a car"], why: "Never crowd into a motorcycle's lane. It gets the full width.", src: "p. 75, 91" },
  { id: "h4", t: "share", q: "Most car-motorcycle crashes happen when:", c: ["A car turns in front of the motorcycle", "The motorcycle runs out of gas", "It's sunny", "The motorcycle is parked"], why: "Over two-thirds involve a car driver turning in front of the motorcyclist.", src: "p. 89" },
  { id: "h5", t: "share", q: "Because they're small, motorcycles often look:", c: ["Farther away and slower than they really are", "Closer and faster than they are", "Exactly as they are", "Bigger at night"], why: "Take a second (and third) look before turning or pulling out.", src: "p. 90" },
  { id: "h6", t: "share", q: "A motorcycle ahead has its turn signal blinking. You should:", c: ["Not assume it's turning until the turn actually starts", "Assume it will turn", "Pass it on the right", "Honk"], why: "Motorcycle signals often don't cancel on their own. Wait until the move clearly starts.", src: "p. 92" },
  { id: "h7", t: "share", q: "Around big trucks and buses, you should:", c: ["Stay where the driver can see you", "Ride right behind them to save gas", "Stay alongside them in their blind spot", "Cut in front of them closely"], why: "Big vehicles have very limited side and rear visibility. Stay visible.", src: "p. 85, 86" },
  { id: "h8", t: "share", q: "Compared to cars, large trucks need:", c: ["More distance to stop", "Less distance to stop", "The same distance", "No room to turn"], why: "Large vehicles need much greater stopping distances.", src: "p. 86" },
  { id: "h9", t: "share", q: "Before opening your car door on the street side, you should:", c: ["Look for bikes and cars first", "Open it quickly", "Honk", "Signal"], why: "Opening a door into traffic, including bicyclists, is a violation.", src: "p. 97" },
  { id: "h10", t: "share", q: "Legally, a bicycle on the road is:", c: ["A vehicle, with the same rights and responsibilities", "A pedestrian", "A toy", "Not allowed on roads"], why: "Bicycles are vehicles and follow the same traffic rules.", src: "p. 97" },
  { id: "h11", t: "share", q: "Riding a bike at night, you must have at least:", c: ["A headlight and a rear reflector", "A bell", "A flag", "Nothing"], why: "At night, a headlight and rear reflector are required. A rear light is recommended too.", src: "p. 98" },
  { id: "h12", t: "share", q: "Bicycles riding on the sidewalk in business districts is:", c: ["Not allowed", "Allowed at any speed", "Required", "Allowed only on weekends"], why: "No sidewalk riding in business districts. Elsewhere, stay at 10 mph or less and yield to pedestrians.", src: "p. 98" },
  { id: "h13", t: "share", q: "Driving near a school bus stop in the morning, kids waiting by the road mean:", c: ["A school bus is nearby and kids may dart out. Be alert", "Nothing special", "You can speed up", "You should honk"], why: "Waiting children signal a school bus in the area and the chance of kids running into the road.", src: "p. 96" },

  // ---------------- EMERGENCIES & CRASHES (Haleiwa) ----------------
  { id: "e1", t: "emergency", q: "Your tire blows out while driving. You should:", c: ["Hold the wheel firmly, stay in your lane, and slow down gradually without braking", "Slam on the brakes", "Swerve to the shoulder fast", "Speed up"], why: "Don't brake right away. Steer straight, ease off, and brake lightly only when you're going slowly.", src: "p. 81" },
  { id: "e2", t: "emergency", q: "Your brakes fail completely. What do you try first?", c: ["Pump the brake pedal quickly", "Turn off the engine", "Pull the parking brake as hard as you can", "Jump out"], why: "Pump the pedal, shift to a lower gear, then apply the parking brake gradually.", src: "p. 81" },
  { id: "e3", t: "emergency", q: "Your rear end skids to the right. You should steer:", c: ["To the right, the way the rear is skidding", "Hard to the left", "Straight and brake hard", "Let go of the wheel"], why: "Ease off the gas, avoid the brakes, and steer the direction the rear is sliding.", src: "p. 83" },
  { id: "e4", t: "emergency", q: "Your right wheels drop off the edge of the pavement. You should:", c: ["Slow down, then steer back on gently when it's safe", "Jerk the wheel to get back on", "Brake hard", "Speed up"], why: "Don't yank the wheel. Keep going, slow down, brake gently, then return.", src: "p. 82" },
  { id: "e5", t: "emergency", q: "Your accelerator sticks and the car keeps speeding up. What is a recommended response?", c: ["Apply firm, steady braking, shift to neutral, and steer to a safe stop", "Pump the brakes repeatedly while staying in drive", "Shift into reverse while moving", "Reach under the pedals while driving"], why: "Use firm, steady braking and shift to neutral to remove engine power from the wheels. Steer off the road to a safe stop, then shut off the engine. Never turn the key to LOCK while moving. Emergency controls vary by vehicle; know your owner manual.", src: "Toyota emergency guidance: sticking accelerator" , url: "https://media.toyota.ca/en/releases/2010/sticking-accelerator-pedal---what-to-do-in-the-event-of-unwanted-acceleration.html" },
  { id: "e6", t: "emergency", q: "An oncoming car is coming at you in YOUR lane. You should:", c: ["Slow down, honk or flash lights, and steer RIGHT", "Steer left into the other lane", "Speed up", "Stop in your lane"], why: "Move right, out of the way, even off the road. Never swerve into the oncoming lane.", src: "p. 82" },
  { id: "e7", t: "emergency", q: "Your car has a small gasoline or electrical fire. Never use:", c: ["Water", "A fire extinguisher", "Sand or dirt", "A blanket"], why: "Water spreads gasoline, oil and electrical fires. Get everyone out first.", src: "p. 84" },
  { id: "e8", t: "emergency", q: "A crash must be reported to police right away if it causes injury, death, or property damage of at least:", c: ["$3,000", "$500", "$10,000", "$50,000"], why: "Any injury, death, or $3,000 or more in damage must be reported immediately.", src: "p. 52" },
  { id: "e9", t: "emergency", q: "After a crash, the first thing you must do is:", c: ["Stop right away (moving off the roadway if possible)", "Drive home and call later", "Post about it", "Leave if no one seems hurt"], why: "Stop, help the injured, warn traffic, and exchange information. Never leave without identifying yourself.", src: "p. 52" },
  { id: "e10", t: "emergency", q: "You scrape a parked car and nobody's around. You must:", c: ["Find the owner or leave a note with your name, address and what happened", "Drive away", "Wait one minute, then leave", "Call a friend"], why: "Locate the owner or leave a written note with your info and the circumstances.", src: "p. 52" },
  { id: "e11", t: "emergency", q: "Someone is hurt in a crash. You should:", c: ["Call for help and avoid moving them unless necessary", "Move them right away", "Give them water", "Help them walk around"], why: "Unskilled handling can make injuries worse. Keep them warm and protected from traffic.", src: "p. 52" },
  { id: "e12", t: "emergency", q: "When should you use your hazard warning (4-way) flashers?", c: ["When your car is stopped in a hazardous spot, never while moving", "When driving in the rain", "When you're parking illegally", "When going slow on the freeway"], why: "Hazards warn that a vehicle is stopped in a dangerous position, so don't use them while moving.", src: "p. 73" },
  { id: "e13", t: "emergency", q: "In a car with anti-lock brakes (ABS), during a hard stop you should:", c: ["Press firmly and don't pump", "Pump the pedal fast", "Use the parking brake", "Tap the brake lightly"], why: "ABS does the pumping for you. Practice not pumping.", src: "p. 19, 80" },
  { id: "e14", t: "emergency", q: "After splashing through ordinary surface water, your brakes feel wet. What should you do once traffic conditions allow?", c: ["Test your brakes by pressing lightly several times", "Speed up to dry the engine", "Turn on your hazards", "Do nothing"], why: "Wet brakes can pull or grip poorly. At low speed, when safe, test them with light applications as described in the manual. Do not drive into floodwater; if brakes do not work normally, stop safely and get help.", src: "p. 70, 76" , url: "https://hidot.hawaii.gov/highways/files/2024/11/2023-Hawaii-Drivers-Manual_5.375x8.375_Final-r3-Digital-071924web.pdf#page=70" },
  { id: "e15", t: "emergency", q: "Your car breaks down and you need help. A good signal is to:", c: ["Raise the hood or tie a white cloth to the door handle", "Leave the car running and walk away", "Stand in the road and wave", "Honk nonstop"], why: "Raise the hood or use a white cloth or sign. Stay locked in until you trust who's helping.", src: "p. 84" },
  { id: "e16", t: "emergency", q: "To register or drive a car in Hawaii, the owner must have:", c: ["Motor vehicle insurance", "A roadside assistance plan", "A second car key", "A dashcam"], why: "Every car, bus or truck owner must carry motor vehicle insurance.", src: "p. 54" },

  // ---------------- SAFE CHOICES (Wahiawa) ----------------
  { id: "a1", t: "safety", q: "Drivers under 21 may not drive with a blood alcohol content (BAC) of:", c: ["0.02 or more", "0.08 or more", "0.10 or more", "0.05 or more"], why: "Zero tolerance: under 21, 0.02 or more is illegal.", src: "p. 56" },
  { id: "a2", t: "safety", q: "For drivers 21 and older, a BAC of ___ or more means \"under the influence\":", c: ["0.08", "0.02", "0.15", "0.20"], why: "A BAC of 0.08 percent or more is under the influence.", src: "p. 56" },
  { id: "a3", t: "safety", q: "\"Implied consent\" means that by driving in Hawaii you've agreed to:", c: ["Alcohol or drug testing under the legal conditions in the implied-consent law", "Any search whenever an officer asks", "Giving up the right to refuse a test", "Lending your car to police"], why: "Implied consent concerns alcohol or drug testing under conditions specified by law, including lawful arrest and required warnings. Refusing can result in license revocation; the current refusal periods differ from the older manual.", src: "HRS 291E-11 and 291E-41" , url: "https://data.capitol.hawaii.gov/hrscurrent/Vol05_Ch0261-0319/HRS0291E/HRS_0291E-0011.htm" },
  { id: "a4", t: "safety", q: "Alcohol is a:", c: ["Depressant. It slows reflexes and judgment", "Stimulant", "Vitamin", "Safe energy boost"], why: "Alcohol is a depressant. Feeling \"up\" just means your inhibitions are lower.", src: "p. 55" },
  { id: "a5", t: "safety", q: "What sobers a person up after drinking?", c: ["Only time", "Black coffee", "A cold shower", "Eating a big meal"], why: "Coffee, food or a cold shower might wake you up, but only time removes alcohol.", src: "p. 55" },
  { id: "a6", t: "safety", q: "An opened alcohol container in the passenger area of a car on a public road is:", c: ["Prohibited", "Fine if the driver isn't drinking", "Fine for passengers over 21", "Fine if it's in a bag"], why: "Open containers in the driver or passenger area are prohibited on public roads.", src: "p. 56" },
  { id: "a7", t: "safety", q: "Over-the-counter cold or allergy medicine can:", c: ["Affect your driving, so check with a doctor first", "Never affect driving", "Make you a better driver", "Replace sleep"], why: "Some non-prescription remedies contain ingredients that impair driving.", src: "p. 56" },
  { id: "a8", t: "safety", q: "Mixing alcohol and other drugs:", c: ["Can be far more dangerous than either alone", "Cancels out the effects", "Is safe in small amounts", "Only matters at night"], why: "The combination can be much more powerful than either one. Never mix them.", src: "p. 56" },
  { id: "a9", t: "safety", q: "Can you drive wearing earbuds or headphones in BOTH ears?", c: ["No, you need to hear sirens and horns", "Yes, at low volume", "Yes, on the freeway", "Yes, if it's a podcast"], why: "Don't drive with headsets covering or in both ears.", src: "p. 59" },
  { id: "a10", t: "safety", q: "For a driver under 18, non-emergency phone use while driving is:", c: ["Prohibited, including hands-free use", "Allowed if hands-free", "Allowed while waiting at a red light", "Allowed on side streets"], why: "Drivers under 18 may not use hands-free mobile devices while driving, except solely for a 911 emergency communication. A traffic-light stop still counts as operating. For ordinary phone use, stop safely out of traffic and turn the engine off.", src: "HRS 291C-137" , url: "https://data.capitol.hawaii.gov/hrscurrent/Vol05_Ch0261-0319/HRS0291C/HRS_0291C-0137.htm" },
  { id: "a11", t: "safety", q: "If you're thrown from a car in a crash, your chance of being killed is about:", c: ["Five times greater", "The same", "Lower", "Twice as low"], why: "Seat belts keep you inside the car. Being thrown out makes death five times more likely.", src: "p. 61" },
  { id: "a12", t: "safety", q: "Without a seat belt, a crash can be deadly at speeds as low as:", c: ["12 mph", "45 mph", "60 mph", "80 mph"], why: "Unbuckled people can be killed at 12 mph. Buckled, people survive crashes up to about 60 mph.", src: "p. 61" },
  { id: "a13", t: "safety", q: "Hawaii law says you can't leave a child under ___ alone in a car for 5 minutes or longer:", c: ["9", "3", "5", "16"], why: "Leaving a child under nine unattended in a vehicle for five minutes or more is prohibited.", src: "p. 64" },
  { id: "a14", t: "safety", q: "How should a shoulder belt fit?", c: ["Snug across the shoulder and chest, with slack removed", "Loose enough to fit a fist beneath it", "Tucked under your arm", "Behind your back"], why: "Wear the lap belt low and snug across your hips, and the shoulder belt across your chest and shoulder without slack. Never put it under your arm or behind your back. Follow your vehicle instructions.", src: "NHTSA: Seat Belts, proper fit" , url: "https://www.nhtsa.gov/vehicle-safety/seat-belts" },
  { id: "a15", t: "safety", q: "You just had a big argument and you're really upset. Best choice:", c: ["Cool off first, or let someone else drive", "Drive fast to blow off steam", "Drive, but blast music", "Drive, it's fine"], why: "Strong emotions make you accident-prone. Take time to cool off or let someone else drive.", src: "p. 24" },
  { id: "a16", t: "safety", q: "If a test shows a BAC of 0.08 or more (or you refuse the test), your license:", c: ["Is taken away and you get a 30-day temporary permit", "Stays the same", "Gets a warning sticker", "Is upgraded"], why: "That's Administrative License Revocation. You can request a hearing.", src: "p. 55" },
  { id: "a17", t: "safety", q: "Your passenger wants to share a funny video while you're driving. You should:", c: ["Keep your eyes on the road, it can wait", "Watch it quickly at a red light", "Hold the phone low and peek", "Watch it, it's short"], why: "Anything that pulls your attention from driving can cause a crash. Handle it before or after the drive.", src: "p. 58" },
];
